use super::*;
#[path="../../../mbse-assurance/tests/support/metrics_source.rs"]
mod source;
fn setup()->(AssuranceWorkspace,Editor,egui::Context){let e=source::editor();let mut w=AssuranceWorkspace::default();w.board=source::requirements(&e.snapshot);w.saved=w.board.as_value().ok();w.statement=w.board.register.drafts.get("new:statement").map(|d|d.text.clone()).unwrap_or_default();w.new_identifier=w.board.register.drafts.get("new:identifier").map(|d|d.text.clone()).unwrap_or_default();w.selected=Some(RequirementId(1));w.open_window();(w,e,egui::Context::default())}
fn render(w:&mut AssuranceWorkspace,e:&Editor,ctx:&egui::Context,events:Vec<egui::Event>)->Vec<String>{let out=ctx.run_ui(egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(2200.,1600.))),focused:true,events,..Default::default()},|_|w.show(ctx,e));let copies=out.platform_output.commands.iter().filter_map(|c|if let egui::OutputCommand::CopyText(s)=c{Some(s.clone())}else{None}).collect();out.drop_without_applying_deltas();copies}
fn settle(w:&mut AssuranceWorkspace,e:&Editor,ctx:&egui::Context){for _ in 0..4{render(w,e,ctx,vec![]);}}
fn click(w:&mut AssuranceWorkspace,e:&Editor,ctx:&egui::Context,key:&str)->Vec<String>{
 settle(w,e,ctx);let mut rect=*w.audit.get(key).unwrap_or_else(||panic!("missing {key}"));
 for _ in 0..32{if rect[2]-rect[0]>5.&&rect[3]-rect[1]>=12.&&rect[1]>=0.&&rect[3]<=1600.{break;}let live=w.audit.values().filter(|v|v[2]>v[0]&&v[3]-v[1]>=12.&&v[1]>=0.&&v[3]<=1600.).collect::<Vec<_>>();let top=live.iter().map(|v|v[1]).fold(100.,f32::min);let bottom=live.iter().map(|v|v[3]).fold(800.,f32::max);let pos=egui::pos2(((rect[0]+rect[2])/2.).clamp(40.,2100.),(bottom-24.).clamp(60.,1530.));let delta=if(rect[1]+rect[3])/2.>(top+bottom)/2.{-320.}else{320.};render(w,e,ctx,vec![egui::Event::PointerMoved(pos),egui::Event::MouseWheel{unit:egui::MouseWheelUnit::Point,delta:egui::vec2(0.,delta),modifiers:egui::Modifiers::NONE,phase:egui::TouchPhase::Move}]);settle(w,e,ctx);rect=*w.audit.get(key).unwrap();}
 assert!(rect[2]-rect[0]>5.&&rect[3]-rect[1]>=12.,"clipped {key}: {rect:?}");let pos=egui::pos2((rect[0]+rect[2])/2.,(rect[1]+rect[3])/2.);let mut copies=Vec::new();for pressed in[true,false]{copies.extend(render(w,e,ctx,vec![egui::Event::PointerMoved(pos),egui::Event::PointerButton{pos,button:egui::PointerButton::Primary,pressed,modifiers:egui::Modifiers::NONE}]));}settle(w,e,ctx);copies
}
fn fill(w:&mut AssuranceWorkspace,e:&Editor,ctx:&egui::Context,key:&str,text:&str){click(w,e,ctx,key);let mut events=vec![egui::Event::Key{key:egui::Key::A,physical_key:None,pressed:true,repeat:false,modifiers:egui::Modifiers{ctrl:true,command:true,..Default::default()}}];if text.is_empty(){events.push(egui::Event::Key{key:egui::Key::Backspace,physical_key:None,pressed:true,repeat:false,modifiers:egui::Modifiers::NONE});}else{events.push(egui::Event::Text(text.into()));}render(w,e,ctx,events);settle(w,e,ctx);}
fn open(w:&mut AssuranceWorkspace,e:&Editor,ctx:&egui::Context){settle(w,e,ctx);if !w.audit.contains_key("metrics:Query"){click(w,e,ctx,"metrics:section");}}
fn query(w:&mut AssuranceWorkspace,e:&Editor,ctx:&egui::Context){open(w,e,ctx);click(w,e,ctx,"metrics:Query");assert!(w.metrics.report.is_some(),"{}",w.metrics.note);}
#[test]
fn metrics_scope_parser_is_canonical_bounded_duplicate_aware_and_preserves_explicit_empty_and_excluded_register(){
 let mut s=State::default();assert_eq!(scope(&s).unwrap(),Scope::default());s.native_all=false;for raw in["","0","01"," 1","+1","-1","١","18446744073709551616"]{s.system=raw.into();assert!(scope(&s).is_err(),"{raw}");}s.system="60082".into();s.requirements_all=false;s.ids="2, 1\n3".into();assert_eq!(scope(&s).unwrap().requirements,RequirementScope::Selected([1,2,3].into_iter().map(RequirementId).collect()));for raw in["1,1","01","0","2;3"]{s.ids=raw.into();assert!(scope(&s).is_err());}s.ids.clear();assert_eq!(scope(&s).unwrap().requirements,RequirementScope::Selected(BTreeSet::new()));s.ids=(1..=10001).map(|i|i.to_string()).collect::<Vec<_>>().join(",");assert!(scope(&s).is_err());s.ids="x".repeat(210001);assert!(scope(&s).is_err());s.include_register=false;assert_eq!(scope(&s).unwrap().requirements,RequirementScope::All);assert_eq!(s.ids.len(),210001);
}
#[test]
fn rendered_metrics_global_system_subset_parent_boundary_and_empty_scopes_match_fixed_counts_without_source_writes(){
 let(mut w,e,ctx)=setup();let native=e.snapshot.clone();let register=w.board.as_value().unwrap();query(&mut w,&e,&ctx);let r=w.metrics.report.as_ref().unwrap();assert_eq!(r.model.top_level_records,21);assert_eq!(r.model.native_by_kind["System"],2);assert_eq!(r.traces.as_ref().unwrap().traces,5);assert_eq!(r.traces.as_ref().unwrap().active_traces,4);assert_eq!(r.traces.as_ref().unwrap().detached_traces,1);
 click(&mut w,&e,&ctx,"metrics:Systems");click(&mut w,&e,&ctx,"metrics:system:60082");assert!(!current(&w,&e));query(&mut w,&e,&ctx);let r=w.metrics.report.as_ref().unwrap();assert_eq!(r.model.top_level_records,1);assert!(r.model.typed.as_ref().unwrap().values().all(|n|*n==0));assert_eq!(r.traces.as_ref().unwrap().traces,5);
 click(&mut w,&e,&ctx,"metrics:Requirements selected");fill(&mut w,&e,&ctx,"metrics:ids","2");query(&mut w,&e,&ctx);let t=w.metrics.report.as_ref().unwrap().traces.as_ref().unwrap();assert_eq!((t.requirements,t.traces,t.active_traces,t.boundary_traces,t.parent_links_crossing_scope),(1,2,2,2,1));
 fill(&mut w,&e,&ctx,"metrics:ids","1");query(&mut w,&e,&ctx);let t=w.metrics.report.as_ref().unwrap().traces.as_ref().unwrap();assert_eq!((t.requirements,t.traces,t.boundary_traces,t.parent_links_crossing_scope),(1,0,1,1));fill(&mut w,&e,&ctx,"metrics:ids","");query(&mut w,&e,&ctx);let t=w.metrics.report.as_ref().unwrap().traces.as_ref().unwrap();assert_eq!((t.requirements,t.traces,t.boundary_traces),(0,0,0));assert_eq!(e.snapshot,native);assert_eq!(w.board.as_value().unwrap(),register);assert!(!w.dirty());
}
#[test]
fn rendered_metrics_missing_or_invalid_scope_retains_historical_report_and_filter_text_without_zero_fallback(){
 let(mut w,e,ctx)=setup();query(&mut w,&e,&ctx);let old=w.metrics.report.as_ref().unwrap().encoded().unwrap();click(&mut w,&e,&ctx,"metrics:Native system");fill(&mut w,&e,&ctx,"metrics:system","1003");click(&mut w,&e,&ctx,"metrics:Query");assert!(w.metrics.note.contains("SYSTEM_SCOPE"));assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);assert!(!current(&w,&e));click(&mut w,&e,&ctx,"metrics:Native all");click(&mut w,&e,&ctx,"metrics:Requirements selected");fill(&mut w,&e,&ctx,"metrics:ids","999999");click(&mut w,&e,&ctx,"metrics:Query");assert!(w.metrics.note.contains("SCOPE_MISSING"));fill(&mut w,&e,&ctx,"metrics:ids","01");assert!(scope(&w.metrics).is_err());assert_eq!(w.metrics.ids,"01");assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);
}
#[test]
fn rendered_metrics_native_and_register_same_counter_changes_stale_prior_report_without_relabeling_its_bytes(){
 let(mut w,mut e,ctx)=setup();query(&mut w,&e,&ctx);let old=w.metrics.report.as_ref().unwrap().encoded().unwrap();let native=e.snapshot.clone();e.snapshot.records.get_mut(&RecordId(1)).unwrap().name="Same counters new native source".into();settle(&mut w,&e,&ctx);assert!(!current(&w,&e));assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);e.snapshot=native;assert!(current(&w,&e));let revision=w.board.register.revision;w.board.register.unknown.insert("same-counter-raw".into(),serde_json::json!({"draft":"9e"}));settle(&mut w,&e,&ctx);assert_eq!(w.board.register.revision,revision);assert!(!current(&w,&e));assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);
}
#[test]
fn completed_register_open_invalidates_metrics_before_the_same_frame_result_and_copy_are_rendered(){
 let(mut w,e,ctx)=setup();query(&mut w,&e,&ctx);let old=w.metrics.report.as_ref().unwrap().encoded().unwrap();let mut loaded=w.board.clone();loaded.register.requirements.get_mut(&RequirementId(1)).unwrap().statement="Different source same IDs and counters".into();let path=PathBuf::from("/workspace/build/builderbob/mbse-craft/milestone1/mock-metrics-register.json");w.path=path.to_string_lossy().into_owned();let frozen=w.close_state().unwrap();let(tx,rx)=mpsc::channel();w.pending=Some(rx);tx.send(Completion::Loaded(Ok((loaded,"synthetic-valid-worker-hash".into())),path,frozen)).unwrap();render(&mut w,&e,&ctx,vec![]);assert!(!audit(&w,&e)["current"].as_bool().unwrap());assert_eq!(w.board.register.requirements[&RequirementId(1)].statement,"Different source same IDs and counters");assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);
}
#[test]
fn rendered_metrics_pending_io_unadmitted_forms_and_close_replace_guards_preserve_previous_report_and_sources(){
 let(mut w,e,ctx)=setup();query(&mut w,&e,&ctx);let old=w.metrics.report.as_ref().unwrap().encoded().unwrap();let before=w.board.as_value().unwrap();let native=e.snapshot.clone();let(_tx,rx)=mpsc::channel();w.pending=Some(rx);assert!(!ready(&w));click(&mut w,&e,&ctx,"metrics:Query");assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);w.pending=None;w.new_identifier="Unadmitted identifier".into();assert!(!ready(&w));click(&mut w,&e,&ctx,"metrics:Query");assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);w.new_identifier.clear();w.close_prompt=true;assert!(!ready(&w));w.close_prompt=false;w.replace_prompt=true;assert!(!ready(&w));w.replace_prompt=false;assert_eq!(e.snapshot,native);assert_eq!(w.board.as_value().unwrap(),before);
}
#[test]
fn rendered_metrics_copy_emits_exact_source_rule_and_scope_json_and_clear_preserves_scope_and_sources(){
 let(mut w,e,ctx)=setup();query(&mut w,&e,&ctx);let expected=serde_json::to_value(w.metrics.report.as_ref().unwrap()).unwrap();let before=w.board.as_value().unwrap();let native=e.snapshot.clone();let copied=click(&mut w,&e,&ctx,"metrics:Copy");let output:serde_json::Value=serde_json::from_str(copied.last().expect("actual GUI copy output")).unwrap();assert_eq!(output,expected);assert_eq!(output["rules_revision"],m::RULES_REVISION);assert_eq!(output["native_source"]["model_revision"],253);assert_eq!(output["native_source"]["snapshot_hash"],e.snapshot.digest());click(&mut w,&e,&ctx,"metrics:Clear");assert!(w.metrics.report.is_none());assert!(w.metrics.native_all&&w.metrics.requirements_all&&w.metrics.include_register);assert_eq!(w.board.as_value().unwrap(),before);assert_eq!(e.snapshot,native);
}
#[test]
fn rendered_metrics_legacy_unavailable_empty_excluded_register_and_session_reopen_remain_distinct_without_migration(){
 let e=Editor::new(mbse_model::stage1::Snapshot::new(mbse_model::stage1::DocumentId("legacy-metrics-ui".into())),"legacy-metrics-ui-runtime".into()).unwrap();let mut w=AssuranceWorkspace::default();w.open_window();let ctx=egui::Context::default();query(&mut w,&e,&ctx);let r=w.metrics.report.as_ref().unwrap();assert_eq!(r.model.top_level_records,1);assert!(r.model.typed.is_none());assert_eq!(r.traces.as_ref().unwrap().requirements,0);assert!(w.audit.contains_key("metrics:typed unavailable"));click(&mut w,&e,&ctx,"metrics:Include register");query(&mut w,&e,&ctx);assert!(w.metrics.report.as_ref().unwrap().traces.is_none());let old=w.metrics.report.as_ref().unwrap().encoded().unwrap();click(&mut w,&e,&ctx,"assurance:Close");assert!(!w.is_visible());w.open_window();settle(&mut w,&e,&ctx);assert_eq!(w.metrics.report.as_ref().unwrap().encoded().unwrap(),old);assert!(AssuranceWorkspace::default().metrics.report.is_none());let foreign=Editor::new(e.snapshot.clone(),"reopened-native-runtime".into()).unwrap();assert!(!current(&w,&foreign));assert!(e.snapshot.extensions.is_none());
}
